'use client';

import { FormEvent, useState } from 'react';
import { ChatMessage, StockEvent } from '@/types/leads';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Send } from 'lucide-react';

interface Props {
  event: StockEvent | null;
}

export default function ChatPanel({ event }: Props) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!input.trim() || !event) return;

    const userMsg: ChatMessage = {
      id: crypto.randomUUID(),
      role: 'user',
      content: input.trim(),
      createdAt: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, userMsg]);
    setInput('');
    setSending(true);

    try {
      const res = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          eventId: event.id,
          messages: [...messages, userMsg].map((m) => ({
            role: m.role,
            content: m.content,
          })),
        }),
      });
      const data: { reply: string } = await res.json();

      const assistantMsg: ChatMessage = {
        id: crypto.randomUUID(),
        role: 'assistant',
        content: data.reply,
        createdAt: new Date().toISOString(),
      };
      setMessages((prev) => [...prev, assistantMsg]);
    } catch (error) {
      console.error('Failed to send chat message:', error);
    } finally {
      setSending(false);
    }
  };

  return (
    <Card className="flex flex-col h-full">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm">Case Chat</CardTitle>
          {event && (
            <span className="text-[11px] text-muted-foreground">
              Context: {event.ticker}
            </span>
          )}
        </div>
      </CardHeader>
      <CardContent className="flex-1 flex flex-col p-0 overflow-hidden">
        <ScrollArea className="flex-1 px-4">
          <div className="space-y-3 py-3">
            {!messages.length && (
              <div className="text-[11px] text-muted-foreground space-y-1">
                <p>Ask about this drop. Examples:</p>
                <p className="pl-2">• "Why might this be a 10b-5 case?"</p>
                <p className="pl-2">
                  • "Summarize other firms' actions here."
                </p>
              </div>
            )}
            {messages.map((m) => (
              <div
                key={m.id}
                className={`flex ${
                  m.role === 'user' ? 'justify-end' : 'justify-start'
                }`}
              >
                <div
                  className={`max-w-[85%] rounded-lg px-3 py-2 text-[11px] whitespace-pre-wrap ${
                    m.role === 'user'
                      ? 'bg-primary text-primary-foreground'
                      : 'bg-muted text-foreground'
                  }`}
                >
                  {m.content}
                </div>
              </div>
            ))}
          </div>
        </ScrollArea>

        <form
          onSubmit={handleSubmit}
          className="border-t border-border px-4 py-3 flex items-center gap-2"
        >
          <Input
            className="flex-1 h-8 text-xs"
            placeholder={
              event
                ? `Ask about ${event.ticker}…`
                : 'Select an event to chat about it…'
            }
            value={input}
            onChange={(e) => setInput(e.target.value)}
            disabled={!event || sending}
          />
          <Button
            type="submit"
            size="sm"
            className="h-8 w-8 p-0"
            disabled={!event || sending || !input.trim()}
          >
            <Send className="h-3.5 w-3.5" />
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

