import type { UIMessage } from "ai"

// Enriched retrieval source returned by the backend chat stream, attached to
// assistant messages via a "sources" data part.
export interface ChatSource {
  document_id: string
  chunk_id: string | null
  title: string | null
  url: string | null
  source_name: string | null
  published_at: string | null
  tickers: string[]
  classification: string | null
  similarity: number
  excerpt: string
}

// Data parts the backend can attach to a chat UI message stream. Keys map to
// AI SDK data part types as "data-<key>", e.g. "thread" -> "data-thread".
export type ChatDataParts = {
  sources: ChatSource[]
  thread: { threadId: string }
}

// UIMessage specialized with our data part shapes. Metadata is left as
// `unknown` (first generic slot) since the backend does not attach any.
export type ChatUIMessage = UIMessage<unknown, ChatDataParts>
