import { getSupabaseServerClient } from "@/lib/supabase/server"
import type { Database, Json } from "@/types/database.types"

export type ChatThreadRow = Database["public"]["Tables"]["chat_threads"]["Row"]

export interface ChatMessageRecord {
  id: string
  role: string
  parts: unknown[]
}

// Finds the most recently updated thread for a given anon session + event,
// or null if none exists yet.
export async function findThread(
  sessionId: string,
  eventId: string
): Promise<ChatThreadRow | null> {
  const supabase = getSupabaseServerClient()
  const { data, error } = await supabase
    .from("chat_threads")
    .select("*")
    .eq("anon_session_id", sessionId)
    .eq("event_id", eventId)
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle()

  if (error) throw error
  return data
}

// Creates a new thread for an anon session + event. Title is truncated to
// 80 chars to match the column's intended display use.
export async function createThread(
  sessionId: string,
  eventId: string,
  title: string
): Promise<ChatThreadRow> {
  const supabase = getSupabaseServerClient()
  const truncatedTitle = title.length > 80 ? title.slice(0, 80) : title

  const { data, error } = await supabase
    .from("chat_threads")
    .insert({
      anon_session_id: sessionId,
      event_id: eventId,
      title: truncatedTitle,
    })
    .select("*")
    .single()

  if (error) throw error
  return data
}

// Looks up a thread by id and confirms it belongs to the given anon session,
// so a client can't read/write another session's thread by guessing its id.
export async function getThreadIfOwned(
  threadId: string,
  sessionId: string
): Promise<ChatThreadRow | null> {
  const supabase = getSupabaseServerClient()
  const { data, error } = await supabase
    .from("chat_threads")
    .select("*")
    .eq("id", threadId)
    .maybeSingle()

  if (error) throw error
  if (!data || data.anon_session_id !== sessionId) return null
  return data
}

// Loads all messages for a thread in insertion order.
export async function loadMessages(
  threadId: string
): Promise<ChatMessageRecord[]> {
  const supabase = getSupabaseServerClient()
  const { data, error } = await supabase
    .from("chat_messages")
    .select("id, role, parts")
    .eq("thread_id", threadId)
    .order("seq", { ascending: true })

  if (error) throw error
  return (data ?? []).map((row) => ({
    id: row.id,
    role: row.role,
    parts: Array.isArray(row.parts) ? row.parts : [],
  }))
}

