export interface ParsedSSEEvent {
  event: string
  data: unknown
}

// Parses the backend's Server-Sent-Events wire format out of a fetch
// Response body stream (POST /api/chat/stream). Blocks are separated by a
// blank line; each block has an "event: <name>" line and a single-line
// "data: <json>" line. Lines starting with ":" are comments and are ignored.
export async function* parseSSEStream(
  stream: ReadableStream<Uint8Array>
): AsyncGenerator<ParsedSSEEvent> {
  const reader = stream.getReader()
  const decoder = new TextDecoder()
  let buffer = ""

  try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) break

      buffer += decoder.decode(value, { stream: true })

      let separatorIndex: number
      while ((separatorIndex = buffer.indexOf("\n\n")) !== -1) {
        const block = buffer.slice(0, separatorIndex)
        buffer = buffer.slice(separatorIndex + 2)

        let eventName: string | null = null
        let dataLine: string | null = null

        for (const line of block.split("\n")) {
          if (line.startsWith(":")) continue
          if (line.startsWith("event:")) {
            eventName = line.slice("event:".length).trim()
          } else if (line.startsWith("data:")) {
            dataLine = line.slice("data:".length).trim()
          }
        }

        if (eventName !== null && dataLine !== null) {
          yield { event: eventName, data: JSON.parse(dataLine) }
        }
      }
    }
  } finally {
    reader.releaseLock()
  }
}
