import { cookies } from "next/headers"
import { createUIMessageStream, createUIMessageStreamResponse, generateId } from "ai"
import { z } from "zod"

import { createThread, getThreadIfOwned, touchThread, upsertMessage } from "@/lib/chat/store"
import { parseSSEStream } from "@/lib/chat/sse"
import type { ChatSource, ChatUIMessage } from "@/types/chat"

// Server-only backend URL. Falls back to the existing NEXT_PUBLIC_ var so
// deployments that haven't yet split a server-only var keep working.
const BACKEND_URL =
  process.env.BACKEND_URL || process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:8000"

const SESSION_COOKIE_NAME = "sl_anon_session"
const SESSION_COOKIE_MAX_AGE = 60 * 60 * 24 * 365 // one year, in seconds

const messagePartSchema = z.looseObject({
  type: z.string(),
})

const chatMessageSchema = z.looseObject({
  id: z.string(),
  role: z.enum(["system", "user", "assistant"]),
  parts: z.array(messagePartSchema),
})

const chatRequestSchema = z.object({
  id: z.string(),
  messages: z.array(chatMessageSchema),
  eventId: z.coerce.string(),
  threadId: z.string().nullable(),
})

type ParsedChatMessage = z.infer<typeof chatMessageSchema>

// Concatenates every "text" part of a message into a single string, in
// order. Non-text parts (data-*, source-url, tool parts, etc.) are ignored.
function extractText(parts: ParsedChatMessage["parts"]): string {
  return parts
    .filter((part): part is { type: "text"; text: string } => {
      return part.type === "text" && typeof (part as { text?: unknown }).text === "string"
    })
    .map((part) => part.text)
    .join("")
}

const BACKEND_UNAVAILABLE_MESSAGE = "The research backend is unavailable. Please try again."

export async function POST(request: Request) {
  const json = await request.json()
  const parsed = chatRequestSchema.safeParse(json)

  if (!parsed.success) {
    return new Response(JSON.stringify({ error: "Invalid request body" }), {
      status: 400,
      headers: { "Content-Type": "application/json" },
    })
  }

  const { messages, eventId, threadId } = parsed.data

  const cookieStore = await cookies()
  let sessionId = cookieStore.get(SESSION_COOKIE_NAME)?.value
  if (!sessionId) {
    sessionId = crypto.randomUUID()
    cookieStore.set(SESSION_COOKIE_NAME, sessionId, {
      httpOnly: true,
      sameSite: "lax",
      path: "/",
      maxAge: SESSION_COOKIE_MAX_AGE,
    })
  }

  let thread = threadId ? await getThreadIfOwned(threadId, sessionId) : null

  if (!thread) {
    const firstUserMessage = messages.find((m) => m.role === "user")
    const title = firstUserMessage ? extractText(firstUserMessage.parts) : "New conversation"
    thread = await createThread(sessionId, eventId, title || "New conversation")
  }

  // Persist the user's new message before calling the backend so a
  // mid-stream failure still leaves the question durably saved. Upsert is
  // idempotent on message id, so a retry of the same submission is safe.
  const lastMessage = messages[messages.length - 1]
  if (lastMessage) {
    await upsertMessage(thread.id, {
      id: lastMessage.id,
      role: lastMessage.role,
      parts: lastMessage.parts,
    })
  }

  const resolvedThreadId = thread.id

  const stream = createUIMessageStream<ChatUIMessage>({
    generateId,
    execute: async ({ writer }) => {
      const assistantMessageId = generateId()
      writer.write({ type: "start", messageId: assistantMessageId })

      // Transient: lets the client learn the resolved thread id via its
      // onData handler, but must never be persisted as message content
      // (store.upsertMessage also strips it defensively).
      writer.write({
        type: "data-thread",
        id: "thread",
        data: { threadId: resolvedThreadId },
        transient: true,
      })

      const backendResponse = await fetch(`${BACKEND_URL}/api/chat/stream`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        signal: request.signal,
        body: JSON.stringify({
          messages: messages.map((m) => ({
            role: m.role,
            content: extractText(m.parts),
          })),
        }),
      })

      if (!backendResponse.ok || !backendResponse.body) {
        throw new Error("Backend request failed")
      }

      const textPartId = "text"
      let textStarted = false

      for await (const evt of parseSSEStream(backendResponse.body)) {
        if (evt.event === "sources") {
          const sources = (evt.data as { sources: ChatSource[] }).sources
          writer.write({ type: "data-sources", id: "sources", data: sources })
          for (const source of sources) {
            if (source.url) {
              writer.write({
                type: "source-url",
                sourceId: source.document_id,
                url: source.url,
              })
            }
          }
        } else if (evt.event === "delta") {
          if (!textStarted) {
            writer.write({ type: "text-start", id: textPartId })
            textStarted = true
          }
          const { text } = evt.data as { text: string }
          writer.write({ type: "text-delta", id: textPartId, delta: text })
        } else if (evt.event === "done") {
          if (textStarted) {
            writer.write({ type: "text-end", id: textPartId })
          }
        } else if (evt.event === "error") {
          if (textStarted) {
            writer.write({ type: "text-end", id: textPartId })
          }
          throw new Error("The assistant encountered an error while generating a response.")
        }
      }
    },
    onError: () => BACKEND_UNAVAILABLE_MESSAGE,
    onFinish: async ({ responseMessage }) => {
      const text = responseMessage.parts
        .filter((part): part is { type: "text"; text: string } => part.type === "text")
        .map((part) => part.text)
        .join("")

      // Partial text captured on abort or mid-stream error is intentionally
      // kept -- a Stop click or a crash shouldn't lose partial output. Only
      // a genuinely empty assistant message is skipped.
      if (text.trim().length > 0) {
        await upsertMessage(resolvedThreadId, {
          id: responseMessage.id,
          role: responseMessage.role,
          parts: responseMessage.parts,
        })
      }
      await touchThread(resolvedThreadId)
    },
  })

  return createUIMessageStreamResponse({ stream })
}
